import os
from typing import Optional, List
from document_client import DocumentClient
from document_models import DocumentPayload, ExtractedReceipt, LineItem
from google.cloud import documentai_v1 as documentai

def extract_receipt_fields(payload: DocumentPayload, config: Optional[dict] = None) -> dict:
    config = config or {}
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
    location = os.environ.get("GOOGLE_CLOUD_LOCATION", "us")
    receipt_processor_id = os.environ.get("GOOGLE_CLOUD_RECEIPT_PROCESSOR_ID")

    if not project_id or not receipt_processor_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID and GOOGLE_CLOUD_RECEIPT_PROCESSOR_ID must be set in environment variables.")

    doc_client = DocumentClient(project_id, location)
    document = doc_client.process_document(
        receipt_processor_id, payload.document_bytes, payload.mime_type
    )

    merchant_name = None
    total_amount = None
    tax_amount = None
    currency = None
    items: List[LineItem] = []

    if document.entities:
        for entity in document.entities:
            if entity.type == "merchant_name":
                merchant_name = entity.mention_text
            elif entity.type == "total_amount":
                total_amount = float(entity.mention_text) if entity.mention_text else None
                if entity.normalized_value and entity.normalized_value.money_value:
                    currency = entity.normalized_value.money_value.currency_code
            elif entity.type == "tax_amount":
                tax_amount = float(entity.mention_text) if entity.mention_text else None
            elif entity.type == "line_item":
                item_description = None
                item_quantity = None
                item_amount = None
                for prop in entity.properties:
                    if prop.type == "description":
                        item_description = prop.mention_text
                    elif prop.type == "quantity":
                        item_quantity = float(prop.mention_text) if prop.mention_text else None
                    elif prop.type == "amount":
                        item_amount = float(prop.mention_text) if prop.mention_text else None
                items.append(LineItem(description=item_description, quantity=item_quantity, amount=item_amount))

    extracted_receipt = ExtractedReceipt(
        merchant=merchant_name,
        tax=tax_amount,
        total=total_amount,
        currency=currency,
        items=items
    )

    return extracted_receipt.dict()

from typing import Dict, Any, List
from document_models import NormalizedExpense, ValidationResult

def validate_document_fields(normalized_expense: NormalizedExpense, required_fields: List[str], min_confidence: float = 0.7) -> ValidationResult:
    missing_fields = []
    low_confidence_fields = {}

    # Check for required fields
    for field in required_fields:
        if not getattr(normalized_expense, field, None):
            missing_fields.append(field)

    # Check confidence scores (example: assume confidence_scores in NormalizedExpense contains field-level confidences)
    # For this example, we'll just check overall confidence if present, or assume 1.0 if not explicit.
    if normalized_expense.confidence_scores:
        for field, score in normalized_expense.confidence_scores.items():
            if score < min_confidence:
                low_confidence_fields[field] = score

    is_valid = not missing_fields and not low_confidence_fields
    message = "Document fields are valid." if is_valid else "Document fields are invalid."

    return ValidationResult(
        is_valid=is_valid,
        missing_fields=missing_fields,
        low_confidence_fields=low_confidence_fields,
        message=message
    )

import os
from typing import Dict, Any
from google.cloud import aiplatform
from google.generativeai.types import HarmCategory, HarmBlockThreshold

def moderate_vendor_text(text: str) -> Dict[str, Any]:
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
    location = os.environ.get("GOOGLE_CLOUD_LOCATION", "us-central1")

    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID must be set in environment variables.")

    aiplatform.init(project=project_id, location=location)

    model = aiplatform.GenerativeModel("gemini-pro") # Using gemini-pro for content moderation

    # Configure safety settings. Adjust thresholds as needed.
    safety_settings = {
        HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
        HarmCategory.HARM_CATEGORY_HATE_SPEECH: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
        HarmCategory.HARM_CATEGORY_HARASSMENT: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
        HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
    }

    try:
        response = model.generate_content(text, safety_settings=safety_settings)
        # If the content is blocked, response.text will raise an exception.
        # Accessing `prompt_feedback` directly to check safety attributes.
        return {
            "original_text": text,
            "is_safe": not response._raw_response.prompt_feedback.block_reason,
            "safety_ratings": [{
                "category": rating.category.name,
                "probability": rating.probability.name,
                "blocked": rating.blocked
            } for rating in response._raw_response.prompt_feedback.safety_ratings]
        }
    except Exception as e:
        # This typically means the content was blocked, and response.text would fail.
        # We can still return safety ratings if available in the exception or raw response.
        return {
            "original_text": text,
            "is_safe": False, # Assuming unsafe if an exception occurred during generation due to safety.
            "error": str(e),
            "safety_ratings": [] # Placeholder, could try to parse from error if detailed.
        }
